import {useEffect,useMemo,useRef} from "react";
import {Platform,Text,View,type ViewProps} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {useLocalStore} from "@/components/nyc-tron/ui/components/useLocalStore";
import {adjustKey} from "@/components/nyc-tron/ui/components/gestures/adjust-keys";
import {keyboardKey,type KeyEventLike} from "@/components/nyc-tron/ui/components/gestures/drag-transport";
import {useLocalPointer} from "@/components/nyc-tron/ui/components/gestures/useLocalPointer";
import {createValueGesture} from "@/components/nyc-tron/ui/components/gestures/value-gesture";
import {assertHsv,hsvToRgb,rgbaToHex,wrapHue,type HsvColor} from "@/components/nyc-tron/ui/components/forge/color";
import {createRingDrag,hueToRingPoint,RING_INNER_FRACTION} from "@/components/nyc-tron/ui/components/forge/color/wheel-geometry";
import {HueRingLayer} from "@/components/nyc-tron/ui/components/forge/color/wheel-layers";
import {border,opacity} from "@/components/nyc-tron/ui/tokens";

/** Props for {@linkcode ColorWheel}. */
export interface ColorWheelProps extends Omit<ViewProps,"children"> {
  /** The committed color. The wheel changes only its hue. */
  readonly value:HsvColor;
  /** Every drag move. */
  readonly onPreview?:(next:HsvColor)=>void;
  /** Once per drag release, key press or screen-reader action that changes the hue. */
  readonly onCommit:(next:HsvColor)=>void;
  /** Largest diameter in layout units; the wheel shrinks to fit its container. @default 240 */
  readonly maxSize?:number;
  /** Degrees per arrow key or screen-reader step. Page Up/Down take 15. @default 1 */
  readonly step?:number;
  readonly disabled?:boolean;
  className?:string;
  unstyled?:boolean;
}

const NO_SELECT=(Platform.OS==="web"?{userSelect:"none",touchAction:"none"}:{}) as object;
const THUMB=30;

/**
 * Controlled hue ring (C-03). Touching the ring jumps to that hue; sliding the
 * finger into the hole switches to fine adjustment (a fifth of the rotation),
 * shown under the wheel, and sliding back out resumes 1:1 tracking. Saturation,
 * value and alpha are never touched, so a gray keeps the hue it had. The center
 * shows the full current color.
 */
export function ColorWheel({
  value,onPreview,onCommit,maxSize=240,step=1,disabled=false,className,unstyled=false,testID,style,...rest
}:ColorWheelProps){
  assertHsv(value);
  if(!Number.isFinite(maxSize)||maxSize<120||maxSize>800)throw new RangeError("maxSize must be 120..800");
  if(!Number.isFinite(step)||step<=0||step>360)throw new RangeError("Hue step must be greater than 0 and at most 360 degrees");
  const [state,store]=useLocalStore(()=>({width:0,preview:undefined as number|undefined,fine:false}));
  const latest=useRef({value,onPreview,onCommit,disabled});
  latest.current={value,onPreview,onCommit,disabled};
  const ring=useMemo(createRingDrag,[]);
  const gesture=useMemo(()=>createValueGesture<number>({
    disabled:()=>latest.current.disabled,
    equals:(a,b)=>a===b,
    preview:h=>{store.set(s=>({...s,preview:h}));latest.current.onPreview?.({...latest.current.value,h});},
    commit:h=>latest.current.onCommit({...latest.current.value,h}),
  }),[store]);
  useEffect(()=>()=>gesture.cancel(),[gesture]);
  const size=Math.max(120,Math.min(maxSize,state.width||maxSize));
  const box={width:size,height:size};
  const end=()=>store.set(s=>({...s,preview:undefined,fine:false}));
  const handlers=useLocalPointer({
    disabled,
    onBegin:p=>{
      gesture.begin(wrapHue(latest.current.value.h));
      const r=ring.begin(p,box,latest.current.value.h);
      store.set(s=>({...s,fine:r.fine}));
      gesture.update(r.hue);
    },
    onMove:p=>{const r=ring.move(p,box);if(r.fine!==state.fine)store.set(s=>({...s,fine:r.fine}));gesture.update(r.hue);},
    onRelease:()=>{gesture.release();end();},
    onCancel:()=>{gesture.cancel();end();},
  });
  const commitHue=(h:number)=>{
    const next=wrapHue(Math.round(h*100)/100);
    if(!disabled&&next!==wrapHue(value.h))onCommit({...value,h:next});
  };
  const onKeyDown=(event:KeyEventLike)=>{
    const intent=adjustKey(keyboardKey(event));
    if(!intent)return;
    if(intent.kind==="cancel"){if(gesture.active){gesture.cancel();end();}return;}
    if(intent.kind==="step")commitHue(value.h+intent.direction*step);
    else if(intent.kind==="page")commitHue(value.h+intent.direction*15);
    else commitHue(intent.kind==="min"?0:359);
    (event as {preventDefault?:()=>void}).preventDefault?.();
  };
  const hue=wrapHue(state.preview??value.h);
  const shownHue=Math.round(hue)%360;
  const thumb=hueToRingPoint(hue,box);
  const inner=size/2*RING_INNER_FRACTION;
  const center=inner*1.5;
  const styled=!unstyled;
  return <View {...rest} testID={testID} {...{className:joinClasses("items-center gap-2",className)}} style={style}
    onLayout={e=>store.set(s=>({...s,width:e.nativeEvent.layout.width}))}>
    <View {...handlers}
      {...{onKeyDown,focusable:!disabled,className:joinClasses(styled&&"focus-visible:ring-2 focus-visible:ring-focus")}}
      accessible accessibilityRole="adjustable" accessibilityLabel="Hue"
      accessibilityHint="Drag around the ring. Slide inward for fine adjustment. Arrow keys change the hue by one degree."
      aria-valuemin={0} aria-valuemax={359} aria-valuenow={shownHue} aria-valuetext={shownHue+" degrees"}
      aria-disabled={disabled}
      accessibilityActions={[{name:"increment",label:"Increase hue"},{name:"decrement",label:"Decrease hue"}]}
      onAccessibilityAction={e=>{
        if(e.nativeEvent.actionName==="increment")commitHue(value.h+step);
        if(e.nativeEvent.actionName==="decrement")commitHue(value.h-step);
      }}
      style={{width:size,height:size,borderRadius:size/2,opacity:disabled?opacity[45]:1,...NO_SELECT}}>
      <HueRingLayer size={size} inner={inner}/>
      <View pointerEvents="none" {...{className:joinClasses(styled&&"bg-surface-raised")}}
        style={{position:"absolute",left:size/2-inner,top:size/2-inner,width:inner*2,height:inner*2,borderRadius:inner}}/>
      <View pointerEvents="none" {...{className:joinClasses(styled&&"border-border")}}
        style={{position:"absolute",left:size/2-center/2,top:size/2-center/2,width:center,height:center,borderRadius:center/2,
          borderWidth:border[1],backgroundColor:rgbaToHex(hsvToRgb({...value,h:hue,alpha:1}),false)}}/>
      <View pointerEvents="none" {...{className:joinClasses(styled&&"border-text")}}
        style={{position:"absolute",left:thumb.x-THUMB/2,top:thumb.y-THUMB/2,width:THUMB,height:THUMB,borderRadius:THUMB/2,
          borderWidth:border[2],alignItems:"center",justifyContent:"center"}}>
        <View {...{className:joinClasses(styled&&"border-surface-raised")}}
          style={{width:THUMB-4,height:THUMB-4,borderRadius:(THUMB-4)/2,borderWidth:border[2],
            backgroundColor:rgbaToHex(hsvToRgb({h:hue,s:1,v:1,alpha:1}),false)}}/>
      </View>
    </View>
    <Text {...{className:joinClasses(styled&&(state.fine?"text-text":"text-text-muted"),styled&&"text-sm")}}
      style={{fontVariant:["tabular-nums"]}}>
      {state.fine?`Hue ${shownHue}° (fine)`:`Hue ${shownHue}°`}
    </Text>
  </View>;
}

import {assertRgba,hsvToRgb,rgbaToHex,type RgbaColor} from "@/components/nyc-tron/ui/components/forge/color";

/*
 * Gradients drawn from solid views. The optional peers that draw real gradients
 * (expo-linear-gradient, Skia) are not required by these controls, and React
 * Native has no conic gradient for a hue ring, so tracks and wheels are built
 * from a fixed number of solid segments. Segment colors are color-model values,
 * not theme colors.
 */

/** Linear interpolation of two colors in 8-bit sRGB, alpha included. */
export function mixRgba(a:RgbaColor,b:RgbaColor,t:number):RgbaColor{
  assertRgba(a);
  assertRgba(b);
  const k=Math.max(0,Math.min(1,t));
  const ch=(x:number,y:number)=>Math.round(x+(y-x)*k);
  return {r:ch(a.r,b.r),g:ch(a.g,b.g),b:ch(a.b,b.b),alpha:a.alpha+(b.alpha-a.alpha)*k};
}

/**
 * `count` `#RRGGBBAA` colors sampled at segment centers along evenly spaced
 * `stops`, for a gradient track drawn as `count` equal views.
 */
export function trackSegments(stops:readonly RgbaColor[],count:number):string[]{
  if(stops.length<2)throw new RangeError("A track needs at least two stops");
  if(!Number.isSafeInteger(count)||count<1||count>512)throw new RangeError("Segment count must be 1..512");
  return Array.from({length:count},(_,i)=>{
    const t=(i+0.5)/count*(stops.length-1);
    const j=Math.min(stops.length-2,Math.floor(t));
    return rgbaToHex(mixRgba(stops[j]!,stops[j+1]!,t-j));
  });
}

/** Pure hues (full saturation and value) at the centers of `count` equal ring segments. */
export function hueSegments(count:number):{angle:number;color:string}[]{
  if(!Number.isSafeInteger(count)||count<3||count>720)throw new RangeError("Hue segment count must be 3..720");
  return Array.from({length:count},(_,i)=>{
    const angle=(i+0.5)*360/count;
    return {angle,color:rgbaToHex(hsvToRgb({h:angle,s:1,v:1,alpha:1}),false)};
  });
}

/**
 * Alphas for `layers` concentric white circles, largest first, that turn a
 * pie of pure hues into a hue/saturation disc. Ring `j` of `layers` (counted
 * from the center) should be white at `1 - (j - 0.5) / layers`, so saturation
 * grows linearly with radius; each circle's alpha is solved from the ones
 * drawn under it.
 */
export function saturationLayerAlphas(layers:number):number[]{
  if(!Number.isSafeInteger(layers)||layers<2||layers>64)throw new RangeError("Layer count must be 2..64");
  const white=(j:number)=>1-(j-0.5)/layers;
  const alphas:number[]=[];
  let below=0;
  for(let j=layers;j>=1;j--){
    const target=white(j);
    alphas.push(j===layers?target:1-(1-target)/(1-below));
    below=target;
  }
  return alphas;
}

/** Composite white fraction at ring `j` (1 = center) after drawing {@linkcode saturationLayerAlphas}. */
export function saturationAtRing(alphas:readonly number[],j:number):number{
  const layers=alphas.length;
  let clear=1;
  for(let i=0;i<=layers-j;i++)clear*=1-alphas[i]!;
  return 1-clear;
}

/** Checkerboard cell count across a track of `width`, for transparency previews. */
export function checkerColumns(width:number,cell=7):number{
  if(!Number.isFinite(width)||width<=0)return 0;
  return Math.ceil(width/cell);
}

import {memo} from "react";
import {View} from "react-native";
import {hsvToRgb,rgbaToHex} from "@/components/nyc-tron/ui/components/forge/color";
import {hueSegments,saturationLayerAlphas} from "@/components/nyc-tron/ui/components/forge/color/segments";

const WHITE=rgbaToHex(hsvToRgb({h:0,s:0,v:1,alpha:1}),false);
const BLACK=rgbaToHex({r:0,g:0,b:0,alpha:1},false);
const RING_SEGMENTS=hueSegments(120);
const DISC_SEGMENTS=hueSegments(96);
const SATURATION=saturationLayerAlphas(24);
const fill={position:"absolute" as const,left:0,top:0,right:0,bottom:0};

/**
 * One wedge per segment: a full-size view rotated about its center, holding a bar
 * from `from` to the edge. React Native transforms rotate clockwise, and hue
 * angles run anticlockwise, hence the negated angle.
 */
function Wedges({size,from,segments}:{size:number;from:number;segments:readonly {angle:number;color:string}[]}){
  const r=size/2;
  const chord=2*Math.PI*r/segments.length*1.15;
  return <>{segments.map(s=><View key={s.angle} pointerEvents="none" style={[fill,{transform:[{rotate:-s.angle+"deg"}]}]}>
    <View style={{position:"absolute",left:r+from,top:r-chord/2,width:r-from,height:chord,backgroundColor:s.color}}/>
  </View>)}</>;
}

/** The hue ring of `ColorWheel`, drawn once per size. `inner` is the hole radius. */
export const HueRingLayer=memo(function HueRingLayer({size,inner}:{size:number;inner:number}){
  return <View pointerEvents="none" style={{width:size,height:size,borderRadius:size/2,overflow:"hidden"}}>
    <Wedges size={size} from={inner*0.9} segments={RING_SEGMENTS}/>
  </View>;
});

/**
 * The hue/saturation disc of `ColorDiscPicker` at full value: pure-hue wedges,
 * then concentric white circles whose alphas make saturation linear in radius,
 * then black at `1 - value`. Only the black layer depends on the color.
 */
export const HueSaturationDiscLayer=memo(function HueSaturationDiscLayer({size,value}:{size:number;value:number}){
  return <View pointerEvents="none" style={{width:size,height:size,borderRadius:size/2,overflow:"hidden"}}>
    <Wedges size={size} from={0} segments={DISC_SEGMENTS}/>
    {SATURATION.map((alpha,i)=>{
      const d=size*(SATURATION.length-i)/SATURATION.length;
      return <View key={i} style={{position:"absolute",left:(size-d)/2,top:(size-d)/2,width:d,height:d,borderRadius:d/2,backgroundColor:WHITE,opacity:alpha}}/>;
    })}
    <View style={[fill,{backgroundColor:BLACK,opacity:1-value}]}/>
  </View>;
});

/** What a key press asks an adjustable control to do; see {@linkcode adjustKey}. */
export type AdjustIntent=
  |{readonly kind:"step";readonly direction:-1|1}
  |{readonly kind:"page";readonly direction:-1|1}
  |{readonly kind:"min"}
  |{readonly kind:"max"}
  |{readonly kind:"cancel"};

/**
 * Maps a key name to an adjustable-control intent, following the ARIA slider
 * pattern: arrows step, Page Up/Down take a large step, Home/End jump to the ends,
 * Escape cancels a drag. With `rtl`, Left increases and Right decreases, so the
 * arrow keys follow a track drawn right to left. Up/Down never flip.
 */
export function adjustKey(key:string|undefined,rtl=false):AdjustIntent|undefined{
  switch(key){
    case "ArrowRight":return {kind:"step",direction:rtl?-1:1};
    case "ArrowLeft":return {kind:"step",direction:rtl?1:-1};
    case "ArrowUp":return {kind:"step",direction:1};
    case "ArrowDown":return {kind:"step",direction:-1};
    case "PageUp":return {kind:"page",direction:1};
    case "PageDown":return {kind:"page",direction:-1};
    case "Home":return {kind:"min"};
    case "End":return {kind:"max"};
    case "Escape":return {kind:"cancel"};
    default:return undefined;
  }
}

import {createContext,useRef} from 'react';
/** Invalidate ephemeral gestures without remounting focused controls or product state. */
export const EditorInteractionScope=createContext<string|null>(null);
let nextInstance=0;
/** Compare cached document signatures by identity without reserializing a whole
 * timeline on every playback tick or nesting its data in child scope strings. */
export function useEditorBoundary(parts:readonly unknown[]):string{
 const ref=useRef<{id:number;version:number;parts:readonly unknown[]}|null>(null);
 ref.current??={id:++nextInstance,version:0,parts:[]};
 const current=ref.current;
 if(parts.length!==current.parts.length||parts.some((part,index)=>!Object.is(part,current.parts[index]))){current.parts=[...parts];current.version++;}
 return current.id+':'+current.version;
}

import type {GestureResponderEvent,PanResponderCallbacks} from "react-native";

/** A point in the responder view's own coordinates (0,0 is its top-left corner). */
export interface LocalPoint {
  readonly x:number;
  readonly y:number;
  /**
   * Touch or stylus force 0..1 when the platform reports one (iOS touches and
   * Apple Pencil, Android styluses). Absent for mice and for touch screens
   * that report no force.
   */
  readonly pressure?:number;
}
/**
 * Callbacks for {@linkcode localPointerConfig}. Unlike `DragTransport`, which reports
 * page coordinates, these report points inside the view, for controls that map a
 * position to a value (a color disc, a seek bar, a clip edge).
 */
export interface LocalPointerHandlers {
  readonly disabled?:boolean;
  onBegin(point:LocalPoint):void;
  onMove(point:LocalPoint):void;
  onRelease(point:LocalPoint):void;
  /** OS termination, or a second pointer when {@linkcode LocalPointerHandlers.onPinch} is absent. */
  onCancel():void;
  /**
   * Two-pointer pinch. `scale` is the current pointer distance over the distance when
   * the second pointer landed; `center` is their midpoint. Once a pinch starts, the
   * gesture ends with {@linkcode LocalPointerHandlers.onPinchEnd} instead of a release.
   */
  onPinch?(scale:number,center:LocalPoint):void;
  onPinchEnd?():void;
}

type Latest={readonly current:LocalPointerHandlers};

const withForce=(point:{x:number;y:number},force:number|undefined):LocalPoint=>
  typeof force==="number"&&Number.isFinite(force)&&force>0?{...point,pressure:Math.min(1,force)}:point;
type Touch={readonly pageX:number;readonly pageY:number};

/**
 * PanResponder callbacks that report view-local points. The grant point is
 * `locationX/Y`, which is relative to the touched view, so every child of the
 * responder view must set `pointerEvents="none"`. Later points add the page-space
 * travel to the grant point; `locationX` on a move would be measured from whatever
 * view the pointer is over.
 */
export function localPointerConfig(latest:Latest):PanResponderCallbacks{
  let origin={x:0,y:0,pageX:0,pageY:0};
  let pinch:{distance:number}|undefined;
  let live=false;
  const local=(pageX:number,pageY:number,force?:number):LocalPoint=>withForce({x:origin.x+pageX-origin.pageX,y:origin.y+pageY-origin.pageY},force);
  const touchesOf=(event:GestureResponderEvent):readonly Touch[]=>event.nativeEvent.touches??[];
  const end=()=>{live=false;pinch=undefined;};
  return {
    onStartShouldSetPanResponder:()=>!latest.current.disabled,
    onMoveShouldSetPanResponder:()=>!latest.current.disabled,
    onPanResponderGrant:event=>{
      const n=event.nativeEvent;
      origin={x:n.locationX,y:n.locationY,pageX:n.pageX,pageY:n.pageY};
      pinch=undefined;
      live=true;
      latest.current.onBegin(withForce({x:n.locationX,y:n.locationY},n.force));
    },
    onPanResponderMove:event=>{
      if(!live)return;
      const touches=touchesOf(event);
      if(touches.length>=2){
        const handlers=latest.current;
        if(!handlers.onPinch){end();handlers.onCancel();return;}
        const [a,b]=touches as [Touch,Touch];
        const distance=Math.hypot(b.pageX-a.pageX,b.pageY-a.pageY);
        if(!pinch){
          // The one-pointer gesture that started this is abandoned, not committed.
          handlers.onCancel();
          pinch={distance:Math.max(distance,1)};
        }
        handlers.onPinch(distance/pinch.distance,local((a.pageX+b.pageX)/2,(a.pageY+b.pageY)/2));
        return;
      }
      if(pinch)return;
      latest.current.onMove(local(event.nativeEvent.pageX,event.nativeEvent.pageY,event.nativeEvent.force));
    },
    onPanResponderRelease:event=>{
      if(!live)return;
      const pinched=pinch!==undefined;
      end();
      if(pinched)latest.current.onPinchEnd?.();
      else latest.current.onRelease(local(event.nativeEvent.pageX,event.nativeEvent.pageY));
    },
    // A parent ScrollView must not take a granted drag; the OS still can.
    onPanResponderTerminationRequest:()=>false,
    onPanResponderTerminate:()=>{
      if(!live)return;
      const pinched=pinch!==undefined;
      end();
      if(pinched)latest.current.onPinchEnd?.();
      else latest.current.onCancel();
    },
    onShouldBlockNativeResponder:()=>true,
  };
}

import {useContext,useLayoutEffect,useMemo,useRef} from "react";
import {PanResponder,type GestureResponderEvent,type GestureResponderHandlers,type PanResponderGestureState,type PanResponderCallbacks} from "react-native";
import {localPointerConfig,type LocalPointerHandlers} from "@/components/nyc-tron/ui/components/gestures/local-pointer";
import {EditorInteractionScope} from '@/components/nyc-tron/ui/components/gestures/editor-interaction-scope';

/**
 * Responder handlers for one view, built once and fed the latest callbacks on
 * every event. Spread the result on the view that defines the local coordinate
 * space; see {@linkcode localPointerConfig} for the `pointerEvents` rule.
 */
export function useLocalPointer(handlers:LocalPointerHandlers):GestureResponderHandlers{
  const scope=useContext(EditorInteractionScope);
  const latest=useRef(handlers);
  useLayoutEffect(()=>{latest.current=handlers;});
  const owner=useRef<{active:boolean;blocked:boolean;last:[GestureResponderEvent,PanResponderGestureState]|null}>({active:false,blocked:false,last:null});
  const config=useMemo<PanResponderCallbacks>(()=>localPointerConfig(latest),[]);
  const cancel=()=>{const s=owner.current;owner.current={active:false,blocked:true,last:null};if(s.active&&s.last)config.onPanResponderTerminate?.(...s.last);};
  useLayoutEffect(()=>{if(scope!==null)cancel();return()=>{if(scope!==null)cancel();};},[scope]);
  return useMemo(()=>PanResponder.create({
    ...config,
    onStartShouldSetPanResponder:(...args)=>{owner.current.blocked=false;return config.onStartShouldSetPanResponder?.(...args)??false;},
    onMoveShouldSetPanResponder:(...args)=>!owner.current.blocked&&(config.onMoveShouldSetPanResponder?.(...args)??false),
    onPanResponderGrant:(...args)=>{owner.current={active:true,blocked:false,last:args};config.onPanResponderGrant?.(...args);},
    onPanResponderMove:(...args)=>{if(!owner.current.active)return;owner.current.last=args;config.onPanResponderMove?.(...args);},
    onPanResponderRelease:(...args)=>{if(!owner.current.active)return;owner.current.active=false;owner.current.last=null;config.onPanResponderRelease?.(...args);},
    onPanResponderTerminate:(...args)=>{if(!owner.current.active)return;owner.current.active=false;owner.current.last=null;config.onPanResponderTerminate?.(...args);},
  }).panHandlers,[config]);
}

/** Callbacks for {@linkcode createValueGesture}. */
export interface ValueGestureCallbacks<T> {
  /** Read on every transition, so a control disabled mid-drag cancels. */
  disabled():boolean;
  equals(a:T,b:T):boolean;
  /** Visual preview during a drag, and the restored start value on cancel. */
  preview(value:T):void;
  /** Called at most once per gesture, on release, and only when the value changed. */
  commit(value:T):void;
}
/** Handle returned by {@linkcode createValueGesture}. */
export interface ValueGesture<T> {
  readonly active:boolean;
  begin(start:T):void;
  /** Previews `next`; ignored when no gesture is active. */
  update(next:T):void;
  release():void;
  /** Restores the start value through `preview`; never commits. */
  cancel():void;
}
/**
 * One value-editing gesture: begin, any number of previews, then a single commit
 * on release or a restore on cancel. Shared by the color tracks and wheels and
 * the timeline edit handles so each engine sees one commit per gesture end.
 */
export function createValueGesture<T>(callbacks:ValueGestureCallbacks<T>):ValueGesture<T>{
  let session:{start:T;current:T}|undefined;
  const cancel=()=>{
    if(!session)return;
    const {start}=session;
    session=undefined;
    callbacks.preview(start);
  };
  return {
    get active(){return session!==undefined;},
    begin(start){
      cancel();
      if(callbacks.disabled())return;
      session={start,current:start};
    },
    update(next){
      if(!session)return;
      if(callbacks.disabled()){cancel();return;}
      if(callbacks.equals(next,session.current))return;
      session.current=next;
      callbacks.preview(next);
    },
    release(){
      if(!session)return;
      const {start,current}=session;
      session=undefined;
      if(callbacks.disabled()){callbacks.preview(start);return;}
      if(!callbacks.equals(start,current))callbacks.commit(current);
    },
    cancel,
  };
}

import {createStore} from "zustand/vanilla";

/**
 * A per-instance store for transient gesture and draft state (a drag preview, a
 * text draft, a measured width). Components use it instead of `useState` so a
 * gesture's bookkeeping lives outside React's render cycle and can be read
 * synchronously from responder callbacks. Created by {@linkcode createLocalStore};
 * components use it through `useLocalStore`. Zustand owns the state; this value-replacement
 * adapter remains independent of React.
 */
export interface LocalStore<T> {
  get():T;
  /** Replaces the state, or derives it from the previous state. Listeners run only when it changes. */
  set(next:T|((previous:T)=>T)):void;
  /** Returns the unsubscribe function. */
  subscribe(listener:()=>void):()=>void;
}

/** Creates a {@linkcode LocalStore}. Equal states (by `Object.is`) do not notify. */
export function createLocalStore<T>(initial:T):LocalStore<T>{
  const store=createStore<{value:T}>(()=>({value:initial}));
  return {
    get:()=>store.getState().value,
    set(next){
      store.setState(current=>{
        const value=typeof next==="function"?(next as (p:T)=>T)(current.value):next;
        return Object.is(value,current.value)?current:{value};
      });
    },
    subscribe(listener){return store.subscribe(()=>listener());},
  };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

import {useRef,useSyncExternalStore} from "react";
import {createLocalStore,type LocalStore} from "@/components/nyc-tron/ui/components/local-store";

/**
 * Creates one {@linkcode LocalStore} for the calling component on first render and
 * subscribes to it. Returns the current state and the store.
 */
export function useLocalStore<T>(initial:()=>T):readonly [T,LocalStore<T>]{
  const ref=useRef<LocalStore<T>|null>(null);
  if(!ref.current)ref.current=createLocalStore(initial());
  const store=ref.current;
  const state=useSyncExternalStore(store.subscribe,store.get,store.get);
  return [state,store] as const;
}

